CREATE OR REPLACE FUNCTION private.accept_practice_invitation(p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    invitation private.practice_invitations;
    member public.practice_memberships;
    actor uuid := auth.uid();
begin
    if actor is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text,0));
    select * into invitation from private.practice_invitations where token_digest=p_token_digest;
    if not found then return '{"status":"invalid-invitation"}'::jsonb; end if;
    perform 1 from public.practices where id=invitation.practice_id for update;
    invitation := private.invitation_for_actor(p_token_digest);
    if invitation.id is null then return '{"status":"invalid-invitation"}'::jsonb; end if;
    select * into member from public.practice_memberships where user_id=actor and state='active';
    if found then
        if member.practice_id <> invitation.practice_id then return '{"status":"other-practice"}'::jsonb; end if;
        return pg_catalog.jsonb_build_object('status','already-member','practiceId',member.practice_id,'role',member.role);
    end if;
    if invitation.state <> 'pending' then return '{"status":"invalid-invitation"}'::jsonb; end if;
    insert into public.practice_memberships (practice_id,user_id,role)
    values(invitation.practice_id,actor,invitation.role)
    on conflict(practice_id,user_id) do update set role=excluded.role,state='active',
        version=practice_memberships.version+1,updated_at=pg_catalog.clock_timestamp()
    returning * into member;
    update private.practice_invitations set state='accepted',accepted_user_id=actor,
        accepted_at=pg_catalog.clock_timestamp(),version=version+1,updated_at=pg_catalog.clock_timestamp()
    where id=invitation.id;
    return pg_catalog.jsonb_build_object('status','success','practiceId',member.practice_id,'role',member.role);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_credential_change(p_practice_id uuid, p_request_id uuid, p_credential_id uuid, p_expected_version integer, p_expected_cycle_id uuid, p_expected_date_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    credential public.credentials;
    cycle public.credential_cycles;
    operation text := case when p_values is null then 'credential-archived' else 'credential-updated' end;
    payload jsonb;
    result jsonb;
    before_data jsonb;
    covered uuid[];
    old_covered uuid[];
    date_changed boolean;
    changed boolean;
begin
    if p_request_id is null or p_credential_id is null or p_expected_cycle_id is null
       or p_expected_version is null or p_expected_version < 1
       or p_expected_date_revision is null or p_expected_date_revision < 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if p_values ? 'status' then return p_values; end if;
    payload := pg_catalog.jsonb_build_object('contract_version', 1, 'operation', operation,
        'credential_id', p_credential_id, 'expected_version', p_expected_version,
        'expected_cycle_id', p_expected_cycle_id, 'expected_date_revision', p_expected_date_revision,
        'values', p_values);
    result := private.register_change_replay(p_practice_id, p_request_id, operation, payload);
    if result is not null then return result; end if;
    select * into credential from public.credentials
    where practice_id = p_practice_id and id = p_credential_id;
    if not found then return '{"status":"not-found"}'::jsonb; end if;
    select * into cycle from public.credential_cycles
    where practice_id = p_practice_id and credential_id = credential.id and cycle_number = 1;
    if not found then raise exception 'missing credential cycle'; end if;
    if credential.archived_at is not null then return '{"status":"archived"}'::jsonb; end if;
    before_data := private.credential_maintenance_projection(credential);
    if credential.version <> p_expected_version or cycle.id <> p_expected_cycle_id
       or cycle.date_revision <> p_expected_date_revision then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', before_data);
    end if;
    changed := true;
    date_changed := false;
    if p_values is not null then
        select coalesce(array_agg(x::uuid order by x::uuid), '{}'::uuid[]) into covered
        from pg_catalog.jsonb_array_elements_text(p_values->'covered_clinician_ids') x;
        if ((p_values->>'owner_clinician_id') is not null and not exists (
            select 1 from public.clinicians where practice_id = p_practice_id
                and id = (p_values->>'owner_clinician_id')::uuid
        )) or exists (select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )) then return '{"status":"invalid-reference"}'::jsonb; end if;
        select coalesce(array_agg(clinician_id order by clinician_id), '{}'::uuid[]) into old_covered
        from public.policy_coverage where practice_id = p_practice_id and credential_id = credential.id;
        date_changed := cycle.end_date is distinct from (p_values->>'end_date')::date
            or cycle.action_deadline is distinct from (p_values->>'action_deadline')::date;
        changed := date_changed or credential.title is distinct from p_values->>'title'
            or credential.type is distinct from p_values->>'type'
            or credential.owner_kind is distinct from p_values->>'owner_kind'
            or credential.owner_clinician_id is distinct from (p_values->>'owner_clinician_id')::uuid
            or credential.issuer is distinct from p_values->>'issuer'
            or credential.jurisdiction is distinct from p_values->>'jurisdiction'
            or old_covered is distinct from covered;
    end if;
    if changed and (credential.version = 2147483647 or (date_changed and cycle.date_revision = 2147483647)) then
        return pg_catalog.jsonb_build_object('status', 'conflict', 'credential', before_data);
    end if;
    if changed then
        if p_values is null then
            update public.credentials set archived_at = pg_catalog.clock_timestamp(),
                version = version + 1, updated_at = pg_catalog.clock_timestamp()
            where practice_id = p_practice_id and id = credential.id returning * into credential;
        else
            delete from public.policy_coverage where practice_id = p_practice_id and credential_id = credential.id;
            update public.credentials set title = p_values->>'title', type = p_values->>'type',
                owner_kind = p_values->>'owner_kind', owner_clinician_id = (p_values->>'owner_clinician_id')::uuid,
                issuer = p_values->>'issuer', jurisdiction = p_values->>'jurisdiction',
                version = version + 1, updated_at = pg_catalog.clock_timestamp()
            where practice_id = p_practice_id and id = credential.id returning * into credential;
            insert into public.policy_coverage (practice_id, credential_id, clinician_id)
            select p_practice_id, credential.id, x from unnest(covered) x;
            if date_changed then
                update public.credential_cycles set end_date = (p_values->>'end_date')::date,
                    action_deadline = (p_values->>'action_deadline')::date,
                    date_revision = date_revision + 1, updated_at = pg_catalog.clock_timestamp()
                where practice_id = p_practice_id and id = cycle.id;
            end if;
        end if;
    end if;
    result := pg_catalog.jsonb_build_object('status', 'success', 'changed', changed,
        'credential', private.credential_maintenance_projection(credential));
    if changed and (date_changed or p_values is null) then
        perform private.dirty_email_reminders(p_practice_id, operation, p_credential_id);
    end if;
    return private.finish_register_change(p_practice_id, p_request_id, credential.id, operation,
        payload, before_data, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_email_reminder_event(p_namespace text, p_event_id text, p_provider_id uuid, p_attempt_id uuid, p_status text, p_from text, p_to text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '1s'
AS $function$
declare attempt private.reminder_message_attempts; endpoint private.reminder_email_endpoints;
    existing private.reminder_delivery_events; anomaly boolean; row record;
begin
    if p_status is null or p_status not in ('sent','delivered','delayed','bounced','complained','failed','suppressed')
        or p_event_id is null or char_length(p_event_id) not between 1 and 256 then return '{"status":"invalid"}'::jsonb; end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id and provider_namespace = p_namespace;
    if not found then return '{"status":"unavailable"}'::jsonb; end if;
    select * into endpoint from private.reminder_email_endpoints where id = attempt.endpoint_id for update;
    -- Suppression locks endpoint then matching jobs in a fixed order; no domain/Auth locks.
    if p_status in ('bounced','complained','suppressed') then
        perform id from private.reminder_jobs where endpoint_id = endpoint.id order by id for update;
    else perform 1 from private.reminder_jobs where id = attempt.job_id for update; end if;
    select * into attempt from private.reminder_message_attempts where id = p_attempt_id for update;
    if attempt.payload->>'from' is distinct from p_from or attempt.payload->'to' <> jsonb_build_array(p_to)
        or p_provider_id is null or (attempt.provider_id is not null and attempt.provider_id <> p_provider_id)
        or (attempt.provider_id is null and attempt.outcome not in ('submitting','uncertain')) then return '{"status":"conflict"}'::jsonb; end if;
    select * into existing from private.reminder_delivery_events where provider_namespace = p_namespace and event_id = p_event_id;
    if found then
        if existing.attempt_id <> attempt.id or existing.provider_id <> p_provider_id or existing.status <> p_status then
            return '{"status":"conflict"}'::jsonb;
        end if;
        return '{"status":"recorded"}'::jsonb;
    end if;
    anomaly := attempt.delivery in ('delivered','bounced','complained','failed','suppressed') and attempt.delivery <> p_status;
    insert into private.reminder_delivery_events (provider_namespace, event_id, practice_id, attempt_id, provider_id, status, anomaly)
    values (p_namespace, p_event_id, attempt.practice_id, attempt.id, p_provider_id, p_status, coalesce(anomaly, false));
    update private.reminder_message_attempts set provider_id = p_provider_id,
        outcome = case when outcome in ('submitting','uncertain') then 'accepted' else outcome end,
        delivery = case when delivery = 'complained' or p_status = 'complained' then 'complained'
            when delivery in ('bounced','suppressed') then delivery
            when p_status in ('bounced','complained','suppressed') then p_status
            when delivery in ('delivered','failed') then delivery else p_status end where id = attempt.id;
    update private.reminder_jobs set state = 'accepted', updated_at = clock_timestamp()
        where id = attempt.job_id and state in ('submitting','uncertain');
    if p_status in ('bounced','complained','suppressed') then
        update private.reminder_email_endpoints set suppressed = true,
            epoch = epoch + case when suppressed then 0 else 1 end,
            reason = case when reason = 'complained' then reason else p_status end where id = endpoint.id;
        with canceled as (
            update private.reminder_jobs set state = 'suppressed', reason = 'email-suppressed', claim_token = null,
                claim_until = null, invalidated_at = clock_timestamp(), updated_at = clock_timestamp()
            where endpoint_id = endpoint.id and state in ('blocked','queued','claimed') returning practice_id, id
        ) insert into private.reminder_job_events (practice_id, job_id, operation)
            select practice_id, id, 'email-suppressed' from canceled;
    end if;
    return '{"status":"recorded"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_sms_provider_opt_out(p_account_sid text, p_messaging_service_sid text, p_phone text, p_message_sid text, p_opt_out_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare endpoint private.sms_phone_endpoints; event private.sms_provider_events;
begin
    if p_opt_out_type is null or p_opt_out_type not in ('STOP','START','HELP') or p_message_sid is null or p_message_sid !~ '^SM[0-9a-fA-F]{32}$' then raise exception 'Invalid event' using errcode='23514'; end if;
    insert into private.sms_phone_endpoints (account_sid,messaging_service_sid,phone_e164) values (p_account_sid,p_messaging_service_sid,p_phone) on conflict do nothing;
    select * into endpoint from private.sms_phone_endpoints where account_sid=p_account_sid and messaging_service_sid=p_messaging_service_sid and phone_e164=p_phone for update;
    select * into event from private.sms_provider_events where account_sid=p_account_sid and message_sid=p_message_sid;
    if found then
        if event.endpoint_id<>endpoint.id or event.opt_out_type<>p_opt_out_type then return '{"status":"conflict"}'::jsonb; end if;
        return '{"status":"success"}'::jsonb;
    end if;
    insert into private.sms_provider_events (account_sid,message_sid,endpoint_id,opt_out_type) values (p_account_sid,p_message_sid,endpoint.id,p_opt_out_type);
    if p_opt_out_type='STOP' then update private.sms_phone_endpoints set provider_blocked=true,suppression_epoch=suppression_epoch+1 where id=endpoint.id; end if;
    return '{"status":"success"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.begin_email_reminder_at(p_job_id uuid, p_claim_token uuid, p_config jsonb, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job private.reminder_jobs; context jsonb; endpoint private.reminder_email_endpoints;
    attempt private.reminder_message_attempts; namespace text := p_config->>'namespace'; payload jsonb; link text; body text;
begin
    -- No arbitrary destination/message input. Only constrained server configuration is accepted.
    if jsonb_typeof(p_config) is distinct from 'object' then return '{"status":"invalid"}'::jsonb; end if;
    if exists (select 1 from jsonb_each_text(p_config) where value is null or char_length(value) > 512)
        or (select count(*) from jsonb_object_keys(p_config)) <> 4
        or not (p_config ?& array['namespace','from','replyTo','appUrl'])
        or namespace !~ '^[a-zA-Z0-9_-]{1,80}$'
        or p_config->>'from' !~ '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9.-]+$'
        or p_config->>'replyTo' !~ '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9.-]+$'
        or p_config->>'appUrl' !~ '^https://[a-zA-Z0-9.-]+(:[0-9]+)?$|^http://127[.]0[.]0[.]1:3000$'
        then return '{"status":"invalid"}'::jsonb; end if;
    select * into job from private.reminder_jobs where id = p_job_id;
    if not found or not private.lock_email_recipient(job.practice_id) then return '{"status":"unavailable"}'::jsonb; end if;
    select * into endpoint from private.reminder_email_endpoints where id = job.endpoint_id for update nowait;
    select * into job from private.reminder_jobs where id = p_job_id for update nowait;
    if job.state <> 'claimed' or job.claim_token is distinct from p_claim_token or job.claim_until <= p_now then
        return '{"status":"stale"}'::jsonb;
    end if;
    context := private.email_reminder_context(job.practice_id, job.credential_id, namespace, p_now);
    if context is null or context->>'reason' is not null
        or (context->>'cycleId')::uuid <> job.cycle_id or (context->>'dateRevision')::integer <> job.date_revision
        or (context->>'membershipId')::uuid <> job.membership_id or (context->>'userId')::uuid <> job.user_id
        or (context->>'selectionVersion')::integer <> job.selection_version
        or (context->>'accountRevision')::bigint <> job.account_revision
        or (context->>'preferenceVersion')::integer <> job.preference_version
        or (context->>'endpointId')::uuid is distinct from job.endpoint_id
        or (context->>'endpointEpoch')::bigint is distinct from job.endpoint_epoch
        or endpoint.suppressed or endpoint.provider_namespace <> namespace
        or endpoint.email is distinct from context->>'email'
        or (context->>'target')::timestamptz is distinct from job.nominal_target
        or context->>'timezone' <> job.timezone
        or job.next_send_at > p_now then
        update private.reminder_jobs set state = 'canceled', reason = coalesce(context->>'reason', 'eligibility-changed'),
            claim_token = null, claim_until = null, invalidated_at = p_now, updated_at = p_now where id = job.id;
        return '{"status":"stale"}'::jsonb;
    end if;
    if private.reminder_next_window(job.nominal_target, job.timezone, p_now) > p_now then
        update private.reminder_jobs set state = 'queued', claim_token = null, claim_until = null,
            next_send_at = private.reminder_next_window(job.nominal_target, job.timezone, p_now), updated_at = p_now where id = job.id;
        return '{"status":"window-closed"}'::jsonb;
    end if;
    attempt.id := gen_random_uuid(); attempt.token := gen_random_uuid();
    link := (p_config->>'appUrl') || '/practice/register/' || job.credential_id::text;
    body := 'A credential renewal needs attention. This reminder was scheduled 60 days before its due date. ' ||
        case when context->>'datePurpose' = 'action-deadline' then 'Action deadline: ' else 'End date: ' end ||
        to_char(job.due_date, 'YYYY-MM-DD') || E'.\nSign in to review the record: ' || link ||
        E'\nThese dates were entered by your practice. Review requirements with the issuer.\nManage reminder emails: ' ||
        (p_config->>'appUrl') || '/practice/reminders';
    payload := jsonb_build_object('from', p_config->>'from', 'to', jsonb_build_array(endpoint.email),
        'reply_to', p_config->>'replyTo', 'subject', 'Credential renewal reminder: 60 days', 'text', body,
        'html', '<p>A credential renewal needs attention. This reminder was scheduled 60 days before its due date.</p><p>' ||
            case when context->>'datePurpose' = 'action-deadline' then 'Action deadline: ' else 'End date: ' end ||
            to_char(job.due_date, 'YYYY-MM-DD') || '.</p><p><a href="' || link || '">Sign in to review the record</a></p>' ||
            '<p>These dates were entered by your practice. Review requirements with the issuer.</p><p><a href="' ||
            (p_config->>'appUrl') || '/practice/reminders">Manage reminder emails</a></p>',
        'tags', jsonb_build_array(jsonb_build_object('name','reminder_attempt','value',attempt.id::text)));
    insert into private.reminder_message_attempts (id, practice_id, job_id, cycle_id, user_id, token,
        endpoint_id, provider_namespace, payload, started_at, deadline)
    values (attempt.id, job.practice_id, job.id, job.cycle_id, job.user_id, attempt.token,
        endpoint.id, namespace, payload, p_now, p_now + interval '30 seconds') on conflict (cycle_id, user_id, channel) do nothing;
    if not found then return '{"status":"consumed"}'::jsonb; end if;
    update private.reminder_jobs set state = 'submitting', claim_token = null, claim_until = null, updated_at = p_now where id = job.id;
    insert into private.reminder_job_events (practice_id, job_id, operation) values (job.practice_id, job.id, 'begin-submit');
    return jsonb_build_object('status','submit', 'attemptId', attempt.id, 'token', attempt.token,
        'payload', payload, 'key', 'reminder-email/' || attempt.id::text);
exception when lock_not_available then return '{"status":"busy"}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.change_reminder_recipient(p_practice_id uuid, p_membership_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    settings private.practice_reminder_settings;
begin
    select * into settings from private.practice_reminder_settings
    where practice_id = p_practice_id for update;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    if settings.membership_id is not distinct from p_membership_id then return; end if;
    update private.practice_reminder_settings set membership_id = p_membership_id,
        version = version + 1, updated_at = pg_catalog.clock_timestamp() where practice_id = p_practice_id;
    insert into private.practice_recipient_events
        (practice_id, actor_user_id, operation, before_membership_id, after_membership_id,
         before_version, after_version, reason)
    values (p_practice_id, auth.uid(),
        case when p_reason is not null then 'member-invalidated'
             when settings.membership_id is null then 'assigned'
             when p_membership_id is null then 'cleared' else 'replaced' end,
        settings.membership_id, p_membership_id, settings.version, settings.version + 1, p_reason);
    if p_membership_id is not null then
        insert into private.reminder_email_preferences (practice_id, user_id)
        select practice_id, user_id from public.practice_memberships where practice_id = p_practice_id and id = p_membership_id
        on conflict do nothing;
    end if;
    perform private.dirty_email_reminders(p_practice_id, 'recipient-changed');
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_email_reminder_at(p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record; job private.reminder_jobs; token uuid := gen_random_uuid();
begin
    for candidate in select id, practice_id, endpoint_id from private.reminder_jobs
        where state in ('queued', 'claimed') and next_send_at <= p_now
            and (state = 'queued' or claim_until <= p_now) order by next_send_at, id limit 100 loop
        if not private.lock_email_recipient(candidate.practice_id) then continue; end if;
        perform 1 from private.reminder_email_endpoints where id = candidate.endpoint_id for update nowait;
        select * into job from private.reminder_jobs where id = candidate.id for update skip locked;
        if not found or job.state not in ('queued', 'claimed') or job.next_send_at > p_now
            or (job.state = 'claimed' and job.claim_until > p_now) then continue; end if;
        if private.reminder_next_window(job.nominal_target, job.timezone, p_now) > p_now then
            update private.reminder_jobs set state = 'queued', claim_token = null, claim_until = null,
                next_send_at = private.reminder_next_window(job.nominal_target, job.timezone, p_now), updated_at = p_now where id = job.id;
            continue;
        end if;
        update private.reminder_jobs set state = 'claimed', claim_token = token, claim_until = p_now + interval '30 seconds', updated_at = p_now
        where id = job.id;
        return jsonb_build_object('jobId', job.id, 'token', token);
    end loop;
    return null;
exception when lock_not_available then return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_sms_verification_check(p_practice_id uuid, p_actor_id uuid, p_request_id uuid, p_challenge_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; enrollment private.practice_sms_enrollments; challenge private.sms_verification_challenges; endpoint private.sms_phone_endpoints; request private.sms_verification_requests; now_at timestamptz:=pg_catalog.clock_timestamp(); payload jsonb; token uuid;
begin
    member := private.sms_member(p_practice_id,p_actor_id,true);
    if p_request_id is null or p_expected_version is null or p_expected_version<1 then raise exception 'Invalid check input' using errcode='23514'; end if;
    select * into challenge from private.sms_verification_challenges where id=p_challenge_id and practice_id=p_practice_id and membership_id=member;
    if not found then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select * into endpoint from private.sms_phone_endpoints where id=challenge.endpoint_id for update;
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=member for update;
    select * into challenge from private.sms_verification_challenges where id=p_challenge_id for update;
    payload := pg_catalog.jsonb_build_object('challenge',p_challenge_id,'version',p_expected_version);
    if exists (select 1 from private.sms_action_receipts where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id) then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select * into request from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id for update;
    now_at := pg_catalog.clock_timestamp();
    if found then
        if request.intent<>'check' or request.payload<>payload then return private.sms_reply(p_practice_id,member,'conflict'); end if;
        if request.state='claimed' and request.lease_until<=now_at then
            update private.sms_verification_requests set state='uncertain',outcome='uncertain' where id=request.id;
            update private.sms_verification_challenges set state='uncertain' where id=challenge.id and state='pending';
        end if;
        return private.sms_reply(p_practice_id,member,case when request.state='complete' then coalesce(request.outcome,'success') else 'uncertain' end);
    end if;
    if enrollment.version<>p_expected_version then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if endpoint.provider_blocked or enrollment.phone_revision<>challenge.phone_revision or enrollment.endpoint_id<>endpoint.id or challenge.state<>'pending'
        or challenge.verification_sid is null or challenge.expires_at<=now_at or challenge.check_count>=5 then return private.sms_reply(p_practice_id,member,'verification-required'); end if;
    if exists (select 1 from private.sms_verification_requests where challenge_id=challenge.id and state in ('claimed','uncertain')) then return private.sms_reply(p_practice_id,member,'busy'); end if;
    token := gen_random_uuid();
    update private.sms_verification_challenges set check_count=check_count+1 where id=challenge.id;
    insert into private.sms_verification_requests (actor_user_id,practice_id,membership_id,request_id,challenge_id,intent,payload,state,claim_token,reserved_at,lease_until)
        values (p_actor_id,p_practice_id,member,p_request_id,challenge.id,'check',payload,'claimed',token,now_at,now_at+interval '30 seconds');
    return pg_catalog.jsonb_build_object('status','claimed','claimToken',token,'phone',endpoint.phone_e164,'accountSid',endpoint.account_sid,'messagingServiceSid',endpoint.messaging_service_sid,'verifyServiceSid',challenge.verify_service_sid,'verificationSid',challenge.verification_sid,'challengeId',challenge.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_sms_verification_send(p_practice_id uuid, p_actor_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; request private.sms_verification_requests; challenge private.sms_verification_challenges; endpoint private.sms_phone_endpoints; enrollment private.practice_sms_enrollments; now_at timestamptz := pg_catalog.clock_timestamp(); token uuid;
begin
    member := private.sms_member(p_practice_id,p_actor_id,true);
    select * into request from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=p_actor_id and request_id=p_request_id and intent='send';
    if not found or request.membership_id<>member then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    select e.* into endpoint from private.sms_phone_endpoints e join private.sms_verification_challenges c on c.endpoint_id=e.id where c.id=request.challenge_id for update of e;
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=member for update;
    select * into challenge from private.sms_verification_challenges where id=request.challenge_id for update;
    select * into request from private.sms_verification_requests where id=request.id for update;
    now_at := pg_catalog.clock_timestamp();
    if request.state<>'prepared' then
        if request.state='claimed' and request.lease_until<=now_at then
            update private.sms_verification_requests set state='uncertain',outcome='uncertain' where id=request.id;
            update private.sms_verification_challenges set state='uncertain' where id=challenge.id and state in ('reserved','pending');
        end if;
        return private.sms_reply(p_practice_id,member,case when request.state='complete' then 'success' else 'uncertain' end);
    end if;
    if endpoint.provider_blocked or enrollment.phone_revision<>challenge.phone_revision or enrollment.endpoint_id<>endpoint.id
        or challenge.state not in ('reserved','pending') or challenge.expires_at<=now_at then return private.sms_reply(p_practice_id,member,'verification-required'); end if;
    if exists (select 1 from private.sms_verification_requests where challenge_id=challenge.id and state in ('claimed','uncertain')) then return private.sms_reply(p_practice_id,member,'busy'); end if;
    if exists (select 1 from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id
        where r.intent='send' and r.reserved_at>now_at-interval '60 seconds' and (r.actor_user_id=p_actor_id or c.endpoint_id=endpoint.id))
        or (select count(*) from private.sms_verification_requests where intent='send' and actor_user_id=p_actor_id and reserved_at>now_at-interval '30 minutes')>=5
        or (select count(*) from private.sms_verification_requests where intent='send' and actor_user_id=p_actor_id and reserved_at>now_at-interval '24 hours')>=10
        or (select count(*) from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id where r.intent='send' and c.endpoint_id=endpoint.id and r.reserved_at>now_at-interval '30 minutes')>=5
        or (select count(*) from private.sms_verification_requests r join private.sms_verification_challenges c on c.id=r.challenge_id where r.intent='send' and c.endpoint_id=endpoint.id and r.reserved_at>now_at-interval '24 hours')>=10
        or (select count(*) from private.sms_verification_requests where intent='send' and practice_id=p_practice_id and reserved_at>now_at-interval '24 hours')>=100 then return private.sms_reply(p_practice_id,member,'rate-limited'); end if;
    token := gen_random_uuid();
    update private.sms_verification_requests set state='claimed',claim_token=token,reserved_at=now_at,lease_until=now_at+interval '30 seconds' where id=request.id;
    return pg_catalog.jsonb_build_object('status','claimed','claimToken',token,'phone',endpoint.phone_e164,'accountSid',endpoint.account_sid,'messagingServiceSid',endpoint.messaging_service_sid,'verifyServiceSid',challenge.verify_service_sid,'verificationSid',challenge.verification_sid,'challengeId',challenge.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.consent_my_practice_sms(p_practice_id uuid, p_request_id uuid, p_expected_version integer, p_consent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; enrollment private.practice_sms_enrollments; endpoint private.sms_phone_endpoints; receipt private.sms_action_receipts; event uuid; payload jsonb;
begin
    member := private.sms_member(p_practice_id,auth.uid(),true);
    if p_consent is distinct from true or p_request_id is null or p_expected_version is null or p_expected_version < 1 then
        raise exception 'Explicit consent required' using errcode = '23514';
    end if;
    select e.* into endpoint from private.sms_phone_endpoints e join private.practice_sms_enrollments s on s.endpoint_id = e.id
        where s.practice_id = p_practice_id and s.membership_id = member for update of e;
    select * into enrollment from private.practice_sms_enrollments where practice_id = p_practice_id and membership_id = member for update;
    payload := pg_catalog.jsonb_build_object('version',p_expected_version,'consent',true,'disclosure','e4-s1-v1');
    select * into receipt from private.sms_action_receipts where practice_id = p_practice_id and actor_user_id = auth.uid() and request_id = p_request_id;
    if found then
        return private.sms_reply(p_practice_id,member,case when receipt.intent = 'consent' and receipt.payload = payload then 'success' else 'conflict' end);
    end if;
    if exists (select 1 from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=auth.uid() and request_id=p_request_id) then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if enrollment.version is distinct from p_expected_version then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if endpoint.id is null or endpoint.provider_blocked or enrollment.verified_revision is distinct from enrollment.phone_revision then
        return private.sms_reply(p_practice_id,member,'verification-required');
    end if;
    if enrollment.consent_event_id is null then
        insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind,disclosure_version,disclosure_text)
        values (p_practice_id,member,auth.uid(),enrollment.phone_revision,endpoint.id,'reminder-consent','e4-s1-v1',private.sms_disclosure('reminder-consent',p_practice_id)) returning id into event;
        update private.practice_sms_enrollments set consent_event_id=event,consent_epoch=endpoint.suppression_epoch,withdrawn=false,version=version+1
        where practice_id=p_practice_id and membership_id=member;
    end if;
    perform private.sms_receipt(p_practice_id,member,auth.uid(),p_request_id,'consent',payload);
    return private.sms_reply(p_practice_id,member,'success');
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice(p_name text, p_timezone text)
 RETURNS practices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result public.practices;
    actor uuid := auth.uid();
begin
    if actor is null or not exists (select 1 from auth.users
                                   where id = actor and email_confirmed_at is not null) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text, 0));
    select p.* into result from public.practices as p
    join public.practice_memberships as m on m.practice_id = p.id
    where m.user_id = actor and m.state = 'active';
    if found then return result; end if;
    insert into public.practices (name, timezone) values (p_name, p_timezone)
    returning * into result;
    insert into public.practice_memberships (practice_id, user_id, role)
    values (result.id, actor, 'administrator');
    insert into private.practice_reminder_settings (practice_id) values (result.id);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_clinician(p_practice_id uuid, p_request_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    payload jsonb;
    result jsonb;
    clinician public.clinicians;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_name);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    payload := pg_catalog.jsonb_build_object('name', normalized);
    result := private.register_replay(p_practice_id, p_request_id, 'clinician-created', payload);
    if result is not null then return result; end if;
    insert into public.clinicians (practice_id, name) values (p_practice_id, normalized)
    returning * into clinician;
    result := pg_catalog.jsonb_build_object('status', 'success', 'clinician',
        pg_catalog.jsonb_build_object('id', clinician.id, 'name', clinician.name,
            'version', clinician.version));
    return private.finish_register_create(p_practice_id, p_request_id, 'clinician-created', payload,
        clinician.id, null, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered);
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_credential_with_details(p_practice_id uuid, p_request_id uuid, p_title text, p_type text, p_owner_kind text, p_owner_clinician_id uuid, p_covered_clinician_ids uuid[], p_issuer text, p_jurisdiction text, p_end_date text, p_action_deadline text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    normalized text;
    issuer text;
    jurisdiction text;
    entered_end_date date;
    entered_action_deadline date;
    covered uuid[] := coalesce(p_covered_clinician_ids, '{}'::uuid[]);
    payload jsonb;
    result jsonb;
    credential public.credentials;
begin
    perform private.require_register_member(p_practice_id, true);
    normalized := private.register_name(p_title);
    issuer := nullif(private.register_name(p_issuer), '');
    jurisdiction := nullif(private.register_name(p_jurisdiction), '');
    if p_request_id is null or normalized is null or char_length(normalized) not between 1 and 120
       or p_type is null or p_type not in ('state_license', 'dea_registration', 'malpractice_policy')
       or p_owner_kind is null or p_owner_kind not in ('clinician', 'practice')
       or (p_owner_kind = 'clinician' and p_owner_clinician_id is null)
       or (p_owner_kind = 'practice' and p_owner_clinician_id is not null)
       or coalesce(array_ndims(covered), 1) <> 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if array_position(covered, null) is not null
       or cardinality(covered) <> (select count(distinct c) from unnest(covered) c)
       or (cardinality(covered) > 0 and (p_type <> 'malpractice_policy' or p_owner_kind <> 'practice')) then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if issuer is not null and char_length(issuer) > 120 then
        return '{"status":"invalid","errors":{"issuer":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    if jurisdiction is not null and char_length(jurisdiction) > 120 then
        return '{"status":"invalid","errors":{"jurisdiction":"Use 1 to 120 characters."}}'::jsonb;
    end if;
    begin
        entered_end_date := private.credential_date(p_end_date);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"endDate":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    begin
        entered_action_deadline := private.credential_date(p_action_deadline);
    exception when datetime_field_overflow or invalid_datetime_format then
        return '{"status":"invalid","errors":{"actionDeadline":"Enter a valid date (YYYY-MM-DD)."}}'::jsonb;
    end;
    if entered_end_date is not null and entered_action_deadline is not null and entered_action_deadline >= entered_end_date then
        return '{"status":"invalid","errors":{"actionDeadline":"The action deadline must be earlier than the end date."}}'::jsonb;
    end if;
    select coalesce(array_agg(c order by c), '{}'::uuid[]) into covered from unnest(covered) c;
    payload := pg_catalog.jsonb_build_object('title', normalized, 'type', p_type,
        'owner_kind', p_owner_kind, 'owner_clinician_id', p_owner_clinician_id,
        'covered_clinician_ids', covered, 'contract_version', 2, 'issuer', issuer,
        'jurisdiction', jurisdiction, 'end_date', pg_catalog.to_char(entered_end_date, 'YYYY-MM-DD'),
        'action_deadline', pg_catalog.to_char(entered_action_deadline, 'YYYY-MM-DD'));
    result := private.register_replay(p_practice_id, p_request_id, 'credential-created', payload);
    if result is not null then return result; end if;
    if (p_owner_clinician_id is not null and not exists (
        select 1 from public.clinicians where practice_id = p_practice_id and id = p_owner_clinician_id
    )) or exists (
        select 1 from unnest(covered) x where not exists (
            select 1 from public.clinicians where practice_id = p_practice_id and id = x
        )
    ) then return '{"status":"invalid-reference"}'::jsonb; end if;
    insert into public.credentials (practice_id, title, type, owner_kind, owner_clinician_id, issuer, jurisdiction)
    values (p_practice_id, normalized, p_type, p_owner_kind, p_owner_clinician_id, issuer, jurisdiction)
    returning * into credential;
    insert into public.policy_coverage (practice_id, credential_id, clinician_id)
    select p_practice_id, credential.id, x from unnest(covered) x;
    update public.credential_cycles cy set end_date = entered_end_date,
        action_deadline = entered_action_deadline,
        updated_at = pg_catalog.clock_timestamp()
    where cy.practice_id = p_practice_id and cy.credential_id = credential.id and cy.cycle_number = 1;
    result := pg_catalog.jsonb_build_object('status', 'success', 'credential',
        private.credential_details_projection(credential));
    return private.finish_register_create(p_practice_id, p_request_id, 'credential-created', payload,
        null, credential.id, result);
end;
$function$

CREATE OR REPLACE FUNCTION private.create_practice_invitation(p_practice_id uuid, p_email text, p_role text, p_token_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    canonical text;
    issued timestamptz;
    result private.practice_invitations;
begin
    perform private.require_administrator(p_practice_id);
    canonical := private.canonical_invitation_email(p_email);
    if p_role is null or p_role not in ('administrator','manager','viewer')
       or p_token_digest is null or p_token_digest !~ '^[0-9a-f]{64}$' then
        raise exception 'Invalid invitation' using errcode='23514';
    end if;
    if exists(select 1 from private.practice_invitations
              where practice_id=p_practice_id and email=canonical and state='pending') then
        return '{"status":"invite-exists"}'::jsonb;
