CREATE OR REPLACE FUNCTION private.get_my_practice_sms_enrollment(p_practice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid;
begin
    member := private.sms_member(p_practice_id, auth.uid(), false);
