CREATE OR REPLACE FUNCTION private.reminder_target(p_date date, p_timezone text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare local_target timestamp; target timestamptz;
begin
    if p_date is null or p_date < date '0001-03-02' or p_date > date '9999-12-31' then return null; end if;
    local_target := p_date - 60 + time '09:00';
    target := local_target at time zone p_timezone;
    if target at time zone p_timezone <> local_target then return null; end if;
    return target;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_recipient_member(p_practice_id uuid, p_edit boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    actor_role text;
begin
    perform 1 from public.practices where id = p_practice_id for update;
    select role into actor_role from public.practice_memberships
    where practice_id = p_practice_id and user_id = auth.uid() and state = 'active';
    if actor_role is null or (p_edit and actor_role not in ('administrator', 'manager')) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    return actor_role in ('administrator', 'manager');
end;
