CREATE OR REPLACE FUNCTION private.set_my_email_reminder_preference(p_practice_id uuid, p_request_id uuid, p_enabled boolean, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pref private.reminder_email_preferences; request private.reminder_email_preference_requests;
    payload jsonb; result jsonb; can_edit boolean;
begin
    can_edit := private.require_recipient_member(p_practice_id, false);
    if p_request_id is null or p_enabled is null or p_expected_version is null or p_expected_version < 1 then
        return '{"status":"invalid"}'::jsonb;
    end if;
    if p_enabled and not can_edit then raise exception 'forbidden' using errcode = '42501'; end if;
    payload := jsonb_build_object('enabled', p_enabled, 'version', p_expected_version);
    select * into request from private.reminder_email_preference_requests
    where practice_id = p_practice_id and user_id = auth.uid() and request_id = p_request_id;
    if found then
        if request.payload <> payload then return '{"status":"request-conflict"}'::jsonb; end if;
        return request.result;
    end if;
    insert into private.reminder_email_preferences (practice_id, user_id) values (p_practice_id, auth.uid()) on conflict do nothing;
    select * into pref from private.reminder_email_preferences where practice_id = p_practice_id and user_id = auth.uid() for update;
    if pref.version <> p_expected_version then return '{"status":"conflict"}'::jsonb; end if;
    if pref.enabled <> p_enabled then
        update private.reminder_email_preferences set enabled = p_enabled, version = version + 1,
            eligible_since = clock_timestamp() where practice_id = p_practice_id and user_id = auth.uid();
        insert into private.reminder_email_preference_events (practice_id, user_id, enabled, version)
        values (p_practice_id, auth.uid(), p_enabled, pref.version + 1);
        -- Cancel only this person's email jobs; assignment/SMS consent stay intact.
        with canceled as (
            update private.reminder_jobs set state = case when state in ('blocked', 'queued', 'claimed') then 'canceled' else state end,
                reason = 'email-preference-changed', claim_token = null, claim_until = null, invalidated_at = clock_timestamp()
            where practice_id = p_practice_id and user_id = auth.uid() returning practice_id, id
        ) insert into private.reminder_job_events (practice_id, job_id, operation, actor_user_id)
            select practice_id, id, 'email-preference-changed', auth.uid() from canceled;
        insert into private.reminder_reconcile_outbox (practice_id) values (p_practice_id)
        on conflict (practice_id) do update set generation = reminder_reconcile_outbox.generation + 1, cursor_id = null, updated_at = clock_timestamp();
    end if;
    result := jsonb_build_object('status', 'success', 'preference', private.get_my_email_reminder_preference(p_practice_id));
    insert into private.reminder_email_preference_requests values (p_practice_id, auth.uid(), p_request_id, payload, result);
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_practice_reminder_recipient(p_practice_id uuid, p_membership_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    settings private.practice_reminder_settings;
begin
    perform private.require_recipient_member(p_practice_id, true);
    if p_expected_version is null or p_expected_version < 1 then
        raise exception 'Invalid version' using errcode = '23514';
    end if;
    select * into settings from private.practice_reminder_settings
    where practice_id = p_practice_id for update;
    if not found then raise exception 'Recipient settings unavailable' using errcode = 'XX000'; end if;
    if settings.version <> p_expected_version then return '{"status":"conflict"}'::jsonb; end if;
    if p_membership_id is not null and not exists (
        select 1 from public.practice_memberships where id = p_membership_id and practice_id = p_practice_id
            and state = 'active' and role in ('administrator', 'manager')
    ) then return '{"status":"invalid-recipient"}'::jsonb; end if;
    perform private.change_reminder_recipient(p_practice_id, p_membership_id, null);
    return pg_catalog.jsonb_build_object('status', 'success',
        'recipient', private.get_practice_reminder_recipient(p_practice_id));
end;
$function$

CREATE OR REPLACE FUNCTION private.sms_member(p_practice_id uuid, p_actor uuid, p_edit boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member public.practice_memberships;
begin
    perform 1 from public.practices where id = p_practice_id for update;
    select * into member from public.practice_memberships
    where practice_id = p_practice_id and user_id = p_actor and state = 'active';
    if not found or (p_edit and member.role not in ('administrator','manager')) then
        raise exception 'forbidden' using errcode = '42501';
    end if;
    return member.id;
end;
$function$

CREATE OR REPLACE FUNCTION private.sms_state(p_practice_id uuid, p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    enrollment private.practice_sms_enrollments;
    endpoint private.sms_phone_endpoints;
    challenge private.sms_verification_challenges;
    member public.practice_memberships;
    consent private.sms_enrollment_events;
    reason text := 'not-started';
    is_verified boolean := false;
    is_consented boolean := false;
    retry_at timestamptz;
begin
    select * into member from public.practice_memberships where practice_id = p_practice_id and id = p_member_id;
    select * into enrollment from private.practice_sms_enrollments where practice_id = p_practice_id and membership_id = p_member_id;
    if enrollment.endpoint_id is not null then
        select * into endpoint from private.sms_phone_endpoints where id = enrollment.endpoint_id;
        if not found then raise exception 'Enrollment unavailable' using errcode = 'XX000'; end if;
    end if;
    select * into challenge from private.sms_verification_challenges
    where practice_id = p_practice_id and membership_id = p_member_id and phone_revision = enrollment.phone_revision
    order by created_at desc, id desc limit 1;
    if enrollment.consent_event_id is not null then
        select * into consent from private.sms_enrollment_events where id = enrollment.consent_event_id
        and practice_id = p_practice_id and membership_id = p_member_id and phone_revision = enrollment.phone_revision
        and kind = 'reminder-consent' and disclosure_version = 'e4-s1-v1';
        if not found then raise exception 'Consent unavailable' using errcode = 'XX000'; end if;
    end if;
    is_verified := coalesce(enrollment.verified_revision = enrollment.phone_revision and enrollment.verified_at is not null, false);
    is_consented := is_verified and consent.id is not null and not endpoint.provider_blocked
        and enrollment.consent_epoch = endpoint.suppression_epoch;
    if coalesce(endpoint.provider_blocked, false) then reason := 'provider-opted-out';
    elsif enrollment.withdrawn then reason := 'withdrawn';
    elsif is_consented then reason := 'enrolled';
    elsif is_verified then reason := 'consent-required';
    elsif challenge.expires_at > pg_catalog.clock_timestamp() and challenge.state in ('reserved','pending','uncertain') then
        reason := case when challenge.state = 'uncertain' or exists (
            select 1 from private.sms_verification_requests where challenge_id = challenge.id
            and state = 'claimed' and lease_until <= pg_catalog.clock_timestamp()
        ) then 'verification-uncertain' else 'verification-pending' end;
    end if;
    select max(r.reserved_at) + interval '60 seconds' into retry_at
    from private.sms_verification_requests r join private.sms_verification_challenges c on c.id = r.challenge_id
    where r.intent = 'send' and (r.actor_user_id = member.user_id or c.endpoint_id = enrollment.endpoint_id);
    return pg_catalog.jsonb_build_object(
        'version', coalesce(enrollment.version, 1), 'phoneRevision', coalesce(enrollment.phone_revision, 0),
        'phoneSuffix', case when endpoint.id is not null then pg_catalog.right(endpoint.phone_e164, 4) else null end,
        'verified', is_verified, 'consented', coalesce(is_consented, false),
        'canEdit', member.state = 'active' and member.role in ('administrator','manager'), 'reason', reason,
        'challengeId', case when challenge.expires_at > pg_catalog.clock_timestamp() and challenge.state in ('reserved','pending','uncertain') then challenge.id else null end,
        'expiresAt', case when challenge.expires_at > pg_catalog.clock_timestamp() and challenge.state in ('reserved','pending','uncertain') then challenge.expires_at else null end,
        'retryAfter', case when retry_at > pg_catalog.clock_timestamp() then retry_at else null end, 'deliveryActive', false);
end;
$function$

CREATE OR REPLACE FUNCTION private.update_practice(p_practice_id uuid, p_name text, p_timezone text, p_expected_version integer)
 RETURNS practices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result public.practices;
    before_timezone text;
begin
    perform private.require_administrator(p_practice_id);
    select timezone into before_timezone from public.practices where id = p_practice_id;
    if p_expected_version is null or p_expected_version < 1 then
        raise exception 'Invalid version' using errcode = '23514';
    end if;
    update public.practices set name = p_name, timezone = p_timezone
    where id = p_practice_id and version = p_expected_version returning * into result;
    if not found then raise exception 'conflict' using errcode = 'PT409'; end if;
    if before_timezone is distinct from p_timezone then
        perform private.dirty_email_reminders(p_practice_id, 'timezone-changed');
    end if;
    return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.withdraw_my_practice_sms(p_practice_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare member uuid; enrollment private.practice_sms_enrollments; receipt private.sms_action_receipts;
begin
    member := private.sms_member(p_practice_id,auth.uid(),false);
    if p_request_id is null then raise exception 'Invalid request' using errcode='23514'; end if;
    select * into enrollment from private.practice_sms_enrollments where practice_id=p_practice_id and membership_id=member for update;
    select * into receipt from private.sms_action_receipts where practice_id=p_practice_id and actor_user_id=auth.uid() and request_id=p_request_id;
    if found then return private.sms_reply(p_practice_id,member,case when receipt.intent='withdraw' then 'success' else 'conflict' end); end if;
    if exists (select 1 from private.sms_verification_requests where practice_id=p_practice_id and actor_user_id=auth.uid() and request_id=p_request_id) then return private.sms_reply(p_practice_id,member,'conflict'); end if;
    if enrollment.practice_id is null then return private.sms_reply(p_practice_id,member,'success'); end if;
    if not enrollment.withdrawn then
        update private.practice_sms_enrollments set consent_event_id=null,consent_epoch=null,withdrawn=true,version=version+1
            where practice_id=p_practice_id and membership_id=member;
        insert into private.sms_enrollment_events (practice_id,membership_id,actor_user_id,phone_revision,endpoint_id,kind)
            values (p_practice_id,member,auth.uid(),enrollment.phone_revision,enrollment.endpoint_id,'withdrawn');
    end if;
    perform private.sms_receipt(p_practice_id,member,auth.uid(),p_request_id,'withdraw','{}'::jsonb);
    return private.sms_reply(p_practice_id,member,'success');
end;
$function$
